// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address nonOwner, uint256 amount, bytes memory data) public {
        vm.assume(nonOwner != address(this) && nonOwner != address(c) && nonOwner != address(0));
        vm.assume(amount <= address(this).balance);
        c.sendMoney(address(0x1111111111111111111111111111111111111111), amount, data);
        vm.prank(nonOwner);
        bool ok;
        try c.withdrawAll() { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
}
